#include<bits/stdc++.h>

using namespace std;

int main(){
  int N,Q;
  cin >> N >> Q;
  vector<int> bk(N+1,0);
  int p=1,q=1;
  for(int i=0;i<Q;i++){
    if(i){cout << " ";}

    int X;
    cin >> X;
    if(X>=1){
      bk[X]++;
      cout << X;
    }
    else{
      while(bk[p]>=q){
        p++;
        if(p==N+1){
          p=1; q++;
        }
      }
      bk[p]++;
      cout << p;
    }
  }
  cout << "\n";
  return 0;
}
